export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "18:00。調查媒體辦公室。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪推門進來。前輩已經走了。桌上留了一張便條——下午的拍攝確認沒問題，下週再整理。辦公室裡只有她一個人。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有坐下。先走到角落的鐵製鎖櫃前。拿出鑰匙。打開。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "鎖櫃裡有幾份舊資料夾。還有一個牛皮紙信封——上次放的鏡背照片。旁邊是另一個更小的信封。封口用膠帶密封。外面寫著一行字。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一輪記憶。未接觸同類硬體資料。Chapter 5。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯在這裡。從那天開始就封著。今天才打開。不是昨天。不是上週。是今天。因為今天之前——我還沒看過任何同類設備的資料。今天看過了。研修教材。退役載體手冊。從現在起，我腦裡已經有了那些圖像。任何新的重畫都會被污染。所以——這份草圖是唯一的未污染基準。打開它。只打開一次。記錄。比較。然後封回去。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把信封拿到桌上。坐下來。打開桌燈。螢光燈管不開。只剩桌燈一圈暖光。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拆開膠帶。抽出裡面的紙。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "三張。A5 大小。鉛筆畫。線條不精確。但每一頁的頁角都寫了日期和一行字——第一輪記憶；未接觸同類硬體資料。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一張。正面圖。掌心長的東西。薄金屬殼。一側畫了幾條短線——標注「金色接點（大概位置）」。殼面上有一個被血遮住的區域。旁邊寫著「血下疑似 T⋯⋯7？」。問號。不確定。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二張。側面圖。薄。邊緣有一處畫了翹起的線條。標注「破邊？翹起？不確定」。問號。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三張。背面。幾乎空白。只畫了一個模糊的長方形。標注「未看清。只記得薄。金屬。」", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯三張。未污染。畫的時候我還沒看過任何載體手冊。沒看過任何研修教材。不知道什麼叫離線設定載體。不知道什麼叫 TKS-SYNC。只知道第一輪千田塞給我的那個東西——掌心長。薄。金屬。一側有金色接點。邊緣破了。血下面可能有 T 和 7。不確定。全都不確定。問號是對的。不確定就是不確定。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把三張草圖攤開在桌上。然後從背包裡拿出手機。打開今天在資料室拍的照片。退役載體手冊。整頁。載體正面圖。側面圖。標籤槽。資產序號。防拆護片。暴力撬出示意圖。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機放在草圖旁邊。螢幕上的載體照片和鉛筆草圖並排。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她翻開筆記本。找到 Chapter 3 和 Chapter 4 整理的第一輪文字記錄。那些是事後寫下的。不是畫的。是文字描述。掌心長。薄金屬。單側接點。破邊。血下可能有字母和數字。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "四份材料攤在桌上。草圖。手冊照片。文字記錄。還有——她腦裡今天看過手冊後浮現的新記憶。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第四份。今天看過手冊後浮現的記憶。必須標記。已受新圖像污染。不作獨立證據。不能拿來跟手冊比對——因為比對的基準本身就來自手冊。那會變成循環。用未污染草圖比對手冊。用文字記錄交叉檢查。新記憶只記錄存在。不列入主證據。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到筆記本空白頁。拿起筆。在頁面頂端寫——", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一輪外殼 vs 退役 TKS-SYNC 離線設定載體。形制比對。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "下面畫了一個表格。六行。四欄。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一行。特徵——掌心長薄金屬殼。Chapter 5 草圖——有。載體手冊——有。結論——相容。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二行。特徵——單側金色接點。Chapter 5 草圖——有。載體手冊——有。結論——相容。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三行。特徵——破裂翹邊。Chapter 5 草圖——有。載體手冊——暴力撬出時可能。結論——相容但非唯一。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第四行。特徵——標籤開頭 T、末尾 7。Chapter 5 草圖——模糊。血下疑似。載體手冊——TOK7／TYO7 類簡稱可能。結論——相容但污染風險高。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第五行。特徵——唯一資產序號。Chapter 5 草圖——第一輪未看清。載體手冊——有。結論——無法比較。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第六行。特徵——正常解鎖結構。Chapter 5 草圖——第一輪未見。載體手冊——有。結論——無法比較。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯六行。兩個相容。一個相容但非唯一。一個相容但污染風險高。兩個無法比較。沒有一行寫「同一物件」。沒有一行寫「確認」。最強的結論——相容。最弱的——無法比較。中間的——相容但有但書。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這個表格。看了很久。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯相容。不是相同。相容的意思是——不排除。不排除不是確認。掌心長薄金屬殼——很多東西都是掌心長薄金屬殼。單側金色接點——同系列載體都有。破裂翹邊——暴力撬出時可能。但其他受力方式也可能造成金屬翹邊。非唯一。標籤 T 和 7——血跡、恐慌、後見資訊。污染風險太高。我現在看著手冊裡的 TOK7 和 TYO7，再回去想第一輪看到的——已經分不清是當時真的看到了，還是現在的知識填補了空白。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拿起手機。打開和佐伯的對話。把比對表格的去識別化版本打進去。沒有寫「第一輪」。沒有寫「千田」。只寫——未污染草圖 vs 退役載體手冊。六行結論。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "幾分鐘後，佐伯回了。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.SaekiTatsuya, character: "佐伯達也", dialogue: "相容不是相同。同系列載體可以裝很多不同內容，外形一樣不代表載入同一設定。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.SaekiTatsuya_Base },
    { characterId: CharacterId.SaekiTatsuya, character: "佐伯達也", dialogue: "TOKYO-7 的 7 和 G07 的 7 仍可能無關。第一輪外殼也可能只是同系列空殼或保護套。妳沒有第一輪照片、重量和序號。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.SaekiTatsuya_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯佐伯說得對。同系列。不是同一個。一個載體系列裡有很多個體。每個個體可以裝不同的設定。外形相同。內容不同。就像同一款手機——每個人的裡面裝的東西都不一樣。我比對的是外形。不是內容。外形相容只說明——它屬於同一系列的可能性不能排除。不說明——它就是手冊裡那一個。不說明——它裝的是 TOKYO-7。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯還有。他說第一輪外殼也可能只是同系列空殼或保護套。空殼。沒有裝任何設定的外殼。保護套。只是外面的屏蔽護片。不是載體本身。第一輪千田塞給我的——可能是完整的載體。可能是空殼。可能只是破掉的護片。我不知道。我只有記憶。記憶裡是掌心長的薄金屬東西。有接點。有破邊。但我不記得它有多重。不記得序號。不記得它是不是實心的。我不確定它是載體還是載體的一部分。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她回覆佐伯。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Message, character: "訊息", dialogue: "知道。相容不是相同。沒有第一輪照片、重量和序號。不畫等號。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "佐伯回了最後一條。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.SaekiTatsuya, character: "佐伯達也", dialogue: "結論先記錄就好，不要解讀。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.SaekiTatsuya_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把手機放回桌上。翻到筆記本比對表那一頁。在表格下方寫——", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "正式結論——與退役 TKS-SYNC 離線設定載體形制高度相似；無法證明為同一物件或同一設定內容。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這行字。看了很久。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯高度相似。無法證明同一。這是今天能說的。最多說到這裡。再多——就是推測。就是我自己想聽的答案。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到下一頁。空白頁。拿起筆。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在頁面中間寫了四行。每行之間留了空隙。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "尖銳物。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "刃物狀金屬片。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "離線設定載體。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田交給我的東西。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "四個名字。四行。同一件東西。四個系統給它的名字。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第一個。尖銳物。車廂安全系統叫的。它看到金屬翹邊。它判斷有威脅。它廣播——請立即放下手中的尖銳物。它不知道那是什麼。它只知道形狀。形狀像刀。像威脅。所以叫尖銳物。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第二個。刃物狀金屬片。警方叫的。他們到場。他們看到金屬。他們看到血。他們看到翹邊。他們分類——刃物狀。金屬片。凶器類。他們不知道它是載體。他們只看到武器的外形。所以叫刃物狀金屬片。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第三個。離線設定載體。工程文件叫的。手冊裡寫的。它有用途。它有程序。它有簽署鏈。它是用來在網路中斷時恢復指定版本的實體裝置。它不是武器。不是凶器。是公共安全系統的復舊工具。工程文件知道它的功能。所以叫離線設定載體。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第四個。千田交給我的東西。我叫的。我不知道它的功能。不知道它的序號。不知道它裝了什麼。我只知道——千田在臨死前把它塞給我。他說「不要救東京」。他沒有時間解釋。所以我只能叫它——千田交給我的東西。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這四行字。四個名字。同一件東西。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯四個名字。四套系統。車廂安全系統看到形狀。警方看到威脅。工程文件看到功能。我看到——一個臨死的人把它塞進我手裡。每一套系統都只看到了一面。每一套系統都根據自己看到的那一面，決定了這件東西應該被叫什麼。被叫什麼——就決定了它會被怎麼處理。被當成尖銳物——就會被放下。被當成刃物狀金屬片——就會被當成證物。被當成離線設定載體——就會被按程序隔離。被當成千田交給我的東西——就會被我記住。帶著走。帶進下一輪。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯系統不是只會藏起物件。也能先替物件決定它應被看成什麼。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把筆放下。靠回椅背。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:30。桌燈的光很暖。窗外是暗的街道。沒有人。偶爾一輛車經過。聲音很輕。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著桌上的四份材料。草圖。手冊照片。文字記錄。和一個被標記為污染的新記憶。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯比對做完了。結論寫了。高度相似。無法證明同一。四個名字寫了。系統的命名權——看見了。但這不是答案。這只是讓問題變得更清楚。那個東西到底是什麼——我仍然不知道。它裝了什麼——我仍然不知道。千田為什麼要把它交給我——我仍然不知道。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把草圖放回信封。重新用膠帶封好。在封口處寫——已開封。比對完成。不再作為獨立比對基準使用。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把信封放回鎖櫃。關上。轉兩圈。鑰匙拔出來。放進背包內袋。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:20。她看了一眼時間。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯還沒結束。研修教材和回復檢查表裡引用了一份文件。設定檔目的記述書。我還沒追那一條。", background: Background.Chapter_15_Ch15_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻開筆記本。找到今天在資料室抄下的引用鏈。研修投影片的「用途」欄寫的是——另見目的記述書。回復檢查紀錄的附註也引用了同一份文件。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拿起手機。打開查詢介面。輸入文件名稱。", background: Background.Chapter_15_Ch15_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕亮起來。", background: Background.Chapter_15_Ch15_Act5_S0 },
];
